static void finish(Fixture *f){if(f->text.entity)CHECK(bh_input_text_cancel(&f->text),"actual text capture canceled");CHECK(bh_config_valid(&f->config),"owned config remains valid");bh_config_dispose(&f->config);bh_network_connection_dispose(&f->sessions);bh_network_game_dispose(&f->game);bh_player_input_owner_dispose(&f->inputs);CHECK(bh_entities_valid(&f->pool)&&bh_entities_dispose(&f->pool)&&bh_sound_queue_dispose(&f->sound),"all real source lifetimes disposed");remove("menu-actions-private.cfg");}
static void video_audio(void){Fixture f;unsigned long before,paints;CHECK(setup(&f),"actual video/audio fixture");strcpy(f.devices[0].name,"Adapter A");strcpy(f.devices[1].name,"Adapter B");strcpy(f.devices[2].name,"ADAPTER A");strcpy((char*)f.config.settings+12,"adapter a");
 put(f.config.settings,4,7);bh_menu_action_video(&f.c,0);CHECK(word(f.config.settings,4)==0&&f.c.refreshes==1,"odd hardware flag toggles via actual refresh");bh_menu_action_video(&f.c,0);CHECK(word(f.config.settings,4)==1,"hardware flag returns one");bh_menu_action_video(&f.c,1);CHECK(!strcmp((char*)f.config.settings+12,"Adapter A"),"device cycle starts after last case-insensitive duplicate and wraps");strcpy((char*)f.config.settings+12,"Adapter B");bh_menu_action_video(&f.c,1);CHECK(!strcmp((char*)f.config.settings+12,"ADAPTER A"),"device cycle copies next real name");put(f.config.settings,8,2);bh_menu_action_video(&f.c,2);CHECK(word(f.config.settings,8)==1,"even resolution flag toggles");before=f.c.refreshes;bh_menu_action_video(&f.c,7);CHECK(f.c.refreshes==before+1,"unassigned valid row still refreshes");
 f.bridge.kind=BH_MENU_EDIT_AUDIO;paints=f.c.paints;bh_menu_action_audio(&f.c,0);bh_menu_action_audio(&f.c,2);CHECK(f.c.paints==paints,"endpoint-max up actions preserve rows");bh_menu_action_audio(&f.c,1);bh_menu_action_audio(&f.c,3);CHECK(!f.c.error&&f.c.paints==paints+4&&f.media.wave_writes==0&&f.media.aux_writes==0,"real absent-endpoint volume getters/setters and both row paints; no volume write");CHECK(bh_text_queue_count(&f.text_queue)>0,"actual menu text queued");finish(&f);}
