 f.menu.selection=2;bh_menu_action_modem(&f.c,2);CHECK(f.text.entity&&!strcmp(f.buffer,"DIAL-12")&&!strcmp(f.text.display,"DIAL-12_")&&f.text.limit==31&&f.text.commit==BH_TEXT_COMMIT_ADDRESS,"modem text action uppercase exact initial paint and actual commit owner");CHECK(bh_input_text_cancel(&f.text),"modem text source cancel");
