 r=f.providers.records;f.settings.selected_network=(BHMenuNetworkRecord*)r;strcpy((char*)r->data,"Modem One");r->data[96]=0;f.failed=0;bh_menu_action_modem(&f.c,3);CHECK(f.failed==1&&f.sessions.enum_calls==0,"modem save then actual initializer failure");bh_network_connection_dispose(&f.sessions);
 f.failed=0;bh_menu_action_tcpip(&f.c,2);CHECK(f.failed==1&&f.sessions.enum_calls==0,"TCP save then actual initializer failure");bh_network_connection_dispose(&f.sessions);
 f.failed=0;bh_menu_action_serial(&f.c,6);CHECK(f.failed==1&&f.sessions.enum_calls==0,"serial save/refresh and actual initializer failure");bh_network_connection_dispose(&f.sessions);CHECK(f.c.refreshes==before,"absent row refresh is verified optional no-op");
