static void graphics_notice(void){Fixture f;float timer=2;unsigned long before;CHECK(setup(&f),"actual message arena fixture");f.panel_identity=0x442950;memcpy(f.panel->payload+4,&timer,4);bh_menu_action_graphics_notice(&f.c,0);memcpy(&timer,f.panel->payload+4,4);CHECK(!strcmp(f.messages.arena,"4Please exit and\nrestart the game\nfor any graphic\nchanges to take\neffect!\n")&&timer==.5f&&f.messages.ring_count==0,"exact original newline notice appended only to actual arena and clamps actual panel timer");before=f.messages.arena_used;f.messages.arena_used=8190;timer=3;memcpy(f.panel->payload+4,&timer,4);bh_menu_action_graphics_notice(&f.c,0);memcpy(&timer,f.panel->payload+4,4);CHECK(f.messages.arena_used==8190&&timer==3,"insufficient arena retains timer and write pointer");f.messages.arena_used=before;finish(&f);}
int __cdecl bh_menu_actions_checkpoint(unsigned long *count){BHMathEnvironment fp;checks=failures=0;if(!bh_math_environment_enter(&fp))return 0;video_audio();profiles();network_options();graphics_notice();bh_math_environment_leave(&fp);if(count)*count+=checks;return !failures;}
#ifdef BH_MENU_ACTIONS_STANDALONE
int main(void){unsigned long n=0;int ok=bh_menu_actions_checkpoint(&n);printf("menu-actions: %lu checks, %lu failures\n",n,failures);return !ok;}
#endif
